SELECT FiltroPorcionesVigentes.CodCotizacion, nombreproductocotiprocesado([FiltroPorcionesVigentes]![CodCotizacion]) AS Nombre, (IIf([Forms]![HistoricoConsumoPorcionesDescargado]![asucursal]=-1,FRConsumoPorcionSumaLocales(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]),FRConsumoPorcion(PorcionGlobalDePorcion([CodCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]))) AS s1, (IIf([Forms]![HistoricoConsumoPorcionesDescargado]![asucursal]=-1,FRConsumoPorcionSumaLocales(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-1),FRConsumoPorcion(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-1))) AS s2, (IIf([Forms]![HistoricoConsumoPorcionesDescargado]![asucursal]=-1,FRConsumoPorcionSumaLocales(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-2),FRConsumoPorcion(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-2))) AS s3, (IIf([Forms]![HistoricoConsumoPorcionesDescargado]![asucursal]=-1,FRConsumoPorcionSumaLocales(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-3),FRConsumoPorcion(PorcionGlobalDePorcion([codCotizacion]),[Forms]![HistoricoConsumoPorcionesDescargado]![semanaactual]-3))) AS s4, StockSinProcesar([FiltroPorcionesVigentes]![CodCotizacion],[Formularios]![HistoricoConsumoPorcionesDescargado]![semanaactual]+1) AS [Stock Final], NombreProovedor(ProovedorPrincipal([FiltroPorcionesVigentes]![CodCotizacion])) AS Proovedor, DLookUp("[ComprasSemana]","[DBIngredientes]","[CodIngrediente]='" & DLookUp("[CodIngrediente]","[Cotizaciones]","[CodCotizacion]=" & [FiltroPorcionesVigentes]![CodCotizacion] & "") & "'")*7 AS [Dias Ciclo Compra], 0 AS [Dias Stock Minimo]
FROM FiltroPorcionesVigentes;

